    "https://api.crustdata.com/company/search",
    headers={
        "authorization": f"Bearer {os.environ['CRUSTDATA_API_KEY']}",
        "x-api-version": "2025-11-01",
    },
    json={
        "search": {
            "query": "software companies",
            "mode": "hybrid",
        },
        "fields": [
            "crustdata_company_id",
        ],
        "limit": 2,
    },
)
print(response.status_code)
print(response.json())

